func TestReviewTrailFindingInputsGroupsBySeverityHeading(t *testing.T) {
	t.Parallel()
	verdict := "request changes\n" +
		"### High\n" +
		"- retry.go:42 — loop ignores ctx\n" +
		"- [low] cache.go:7 — stale entry\n" +
		"- Low: rename the helper in util.go:5\n" +
		"**Low:**\n" +
		"- docs typo in README.md:3\n" +
		"## Medium\n" +
		"handler.go:9 drops the error.\n" +
		"### Nit\n" +
		"None.\n" +
		"### Low\n" +
		"- wording on the critical path section in docs.md:4\n"

	inputs := reviewTrailFindingInputs("", cliReview.TrailReport{Prose: verdict})
	want := []struct{ body, severity string }{
		{"loop ignores ctx", "high"},
		{"stale entry", "low"},
		{"rename the helper", "low"},
		{"docs typo", "low"},
		{"drops the error", "medium"},
		{"critical path section", "low"},
	}
	if len(inputs) != len(want) {
		bodies := make([]string, len(inputs))
		for i, in := range inputs {
			bodies[i] = *in.Body
		}
		t.Fatalf("inputs = %#v, want %d findings and no heading findings", bodies, len(want))
	}
	for i, w := range want {
		if !strings.Contains(*inputs[i].Body, w.body) || strings.Contains(*inputs[i].Body, "#") {
			t.Errorf("body[%d] = %q, want it to hold %q without a heading", i, *inputs[i].Body, w.body)
		}
		if inputs[i].Severity == nil || *inputs[i].Severity != w.severity {
			t.Errorf("severity[%d] = %v, want %s", i, inputs[i].Severity, w.severity)
		}
	}
}

func TestReviewTrailFindingInputsSeverityGroupShapes(t *testing.T) {
	t.Parallel()
	verdict := "### P1 — must fix\n" +
		"- retry.go:42 unbounded retry\n" +
		"## Medium\n\n" +
		"### Token logged in auth.go:10\n" +
		"Logged at info.\n\n" +
		"**Cache stale** (cache.go:7)\n" +
		"Never evicted.\n\n" +
		"### Low\n" +
		"None.\n\n" +
		"Overall the change is well-scoped.\n"

	inputs := reviewTrailFindingInputs("", cliReview.TrailReport{Prose: verdict})
	// The sub-heading's finding holds everything up to the next heading.
	want := []struct{ body, severity string }{
		{"unbounded retry", "high"},
		{"Cache stale", "medium"},
	}
	if len(inputs) != len(want) {
		bodies := make([]string, len(inputs))
		for i, in := range inputs {
			bodies[i] = *in.Body
		}
		t.Fatalf("inputs = %#v, want %d findings", bodies, len(want))
	}
	for i, w := range want {
		if !strings.Contains(*inputs[i].Body, w.body) || strings.Contains(*inputs[i].Body, "#") {
			t.Errorf("body[%d] = %q, want it to hold %q without a heading", i, *inputs[i].Body, w.body)
		}
		if inputs[i].Severity == nil || *inputs[i].Severity != w.severity {
			t.Errorf("severity[%d] = %v, want %s", i, inputs[i].Severity, w.severity)
		}
	}
}

